  updated_at = now();

DO $$
DECLARE
  expected CONSTANT integer := 61;
  present integer;
BEGIN
  SELECT count(*) INTO present
    FROM public.report_type_registry
   WHERE type_id = ANY (ARRAY[
     'readiness.executive_digest',
     'provenance.evidence_trace_report',
     'compliance.audit_assurance_pack',
     'usa_fda.pma_submission_readiness',
     'usa_fda.estar_510k_equivalence_matrix',
