     'etmf.completeness_pack',
     'research_compliance.training_status',
     'effort.certification_register',
     'research_security.coi_register',
     'research_admin.scorecard',
     'prediction.regulatory_forecast',
     'prediction.crl_rtf_premortem',
     'usa_fda.ind_safety_readiness',
     'usa_fda.nda_bla_filing_readiness',
     'usa_fda.crl_response_intelligence',
     'usa_fda.type_bcd_meeting_brief',
     'usa_fda.de_novo_classification_pack',
     'ema.maa_loq_response_pack',
     'ema.variation_readiness',
     'ema.psur_pbrer_pack',
     'ema.scientific_advice_brief',
     'eu_mdr.technical_documentation_readiness',
     'eu_mdr.cer_per_completeness',
     'eu_ivdr.performance_evaluation_readiness',
     'japan_pmda.jnda_shonin_readiness',
     'japan_pmda.consultation_brief',
     'japan_pmda.reexamination_pack',
     'canada_hc.nds_snds_readiness',
     'canada_hc.device_licence_readiness',
     'uk_mhra.maa_readiness',
     'uk_mhra.ilap_pathway_brief',
     'australia_tga.prescription_medicine_readiness',
     'australia_tga.artg_device_inclusion_readiness',
     'korea_mfds.drug_registration_readiness',
     'switzerland_swissmedic.maa_readiness',
     'brazil_anvisa.registration_dossier_readiness',
     'global.cross_region_submission_comparison',
     'global.harmonization_gap_matrix',
     'global.label_currency_matrix',
     'pv.dsur_readiness',
     'pv.signal_management_report',
     'prediction.deficiency_risk',
     'prediction.readiness_trajectory',
     'prediction.trial_pos'
   ]);
  IF present < expected THEN
    RAISE EXCEPTION 'report_type_registry holds % of the % seeded report types after the seed; the file is incomplete or a row was refused.', present, expected;
  END IF;
END $$;
